"""Write CHANGELOG.md from the titles of the commits.

Why this module exists
A changelog written by hand drifts from what was done. This script builds it from
the commit titles only, so that the history is the single source and the file can
be checked against it before a publication.

Usage: python3 scripts/generate_changelog.py [--check]
"""

import pathlib
import subprocess
import sys

ROOT = pathlib.Path(__file__).resolve().parent.parent

HEADER = (
    "# Changelog\n"
    "\n"
    "Generated by scripts/generate_changelog.py from the titles of the commits. "
    "Do not edit by hand.\n"
)

# The first word of a commit title decides its section; a title that starts with
# another word goes to the last one.
SECTIONS = (
    ("Added", ("Add", "Create", "Introduce", "Implement", "Write", "Port")),
    ("Fixed", ("Fix", "Correct", "Repair")),
    ("Documentation", ("Document", "Record", "Describe", "Explain")),
    ("Tests", ("Test", "Check", "Prove", "Cover")),
)
OTHER = "Changed"
SKIPPED_PREFIXES = ("Merge ",)


def section_of(title):
    first = title.split(None, 1)[0] if title.split() else ""
    for name, words in SECTIONS:
        if first in words:
            return name
    return OTHER


def render(titles):
    """The text of the changelog for `titles`, newest first. Merge commits and
    empty titles are left out; each section keeps the order of the history."""
    kept = [
        title.strip()
        for title in titles
        if title.strip() and not title.startswith(SKIPPED_PREFIXES)
    ]
    grouped = {name: [] for name, _ in SECTIONS}
    grouped[OTHER] = []
    for title in kept:
        grouped[section_of(title)].append(title)
    lines = [HEADER, "## Unreleased", ""]
    for name in [name for name, _ in SECTIONS] + [OTHER]:
        if not grouped[name]:
            continue
        lines.append("### " + name)
        lines.append("")
        lines.extend("- " + title for title in grouped[name])
        lines.append("")
    if not kept:
        lines.append("Nothing yet.")
        lines.append("")
    return "\n".join(lines).rstrip("\n") + "\n"


def git_titles(root):
    """The title line of every commit reachable from HEAD, newest first."""
    completed = subprocess.run(
        ["git", "-C", str(root), "log", "--no-merges", "--format=%s"],
        capture_output=True,
        text=True,
        check=True,
        timeout=60,
    )
    return completed.stdout.splitlines()


def main(arguments, root=ROOT):
    check_only = arguments == ["--check"]
    if arguments and not check_only:
        sys.stderr.write("usage: python3 scripts/generate_changelog.py [--check]\n")
        return 2
    try:
        text = render(git_titles(root))
    except (OSError, subprocess.SubprocessError) as error:
        sys.stderr.write("cannot read the history: %s\n" % type(error).__name__)
        return 1
    target = pathlib.Path(root) / "CHANGELOG.md"
    current = target.read_text(encoding="utf-8") if target.exists() else None
    if check_only:
        if current != text:
            sys.stderr.write("CHANGELOG.md is out of date: run scripts/generate_changelog.py\n")
            return 1
        return 0
    if current != text:
        with open(target, "w", encoding="utf-8", newline="\n") as handle:
            handle.write(text)
        sys.stderr.write("written: CHANGELOG.md\n")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
